CREATE TABLE IF NOT EXISTS acknowledgements(id INTEGER PRIMARY KEY,accepted_at TEXT NOT NULL,version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY,name TEXT NOT NULL,owner TEXT NOT NULL,scope TEXT NOT NULL,expires_at TEXT,state TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ap_clients(mac TEXT PRIMARY KEY,ip TEXT,hostname TEXT,first_seen TEXT,last_seen TEXT,online INTEGER NOT NULL DEFAULT 0,state TEXT);
CREATE TABLE IF NOT EXISTS ap_events(id INTEGER PRIMARY KEY,mac TEXT,ip TEXT,hostname TEXT,event TEXT NOT NULL,created_at TEXT NOT NULL);
